    <div class="settings-form">
        <form id="alert-form" class="stack-form"><input type="hidden" name="is_enabled" value="1"><input type="hidden" name="ai_commentary_enabled" value="1"><label>Stock<select name="stock_id" required><option value="">Select a stock</option><?php foreach($stocks as $stock):?><option value="<?= (int)$stock['id'] ?>"><?= e($stock['symbol'].' · '.$stock['company_name']) ?></option><?php endforeach;?></select></label><label>Alert name<input type="text" name="name" maxlength="120" placeholder="AAPL 0.2% move" required></label><div class="form-grid"><label>Threshold type<select name="threshold_type" id="threshold-type"><option value="percent">Percentage change</option><option value="absolute_price">Absolute price movement</option><option value="target_price">Target price</option></select></label><label>Threshold <span id="threshold-unit">%</span><input type="number" name="threshold_value" min="0.00000001" step="0.00000001" value="0.2" required></label></div><div class="form-grid"><label>Direction<select name="direction"><option value="both">Both</option><option value="increase">Increase</option><option value="decrease">Decrease</option></select></label><label>Reference<select name="reference_type"><option value="previous_close">Previous close</option><option value="last_alert_price">Last alert price</option><option value="average_cost">Average purchase price</option><option value="fixed_price">Fixed reference price</option></select></label></div><label>Fixed reference price (only when selected)<input type="number" name="reference_price" min="0" step="0.00000001"></label><div class="form-grid"><label>Check interval<select name="check_interval_minutes"><option value="5">5 minutes</option><option value="15">15 minutes</option><option value="30">30 minutes</option><option value="60">60 minutes</option></select></label><label>Cooldown (minutes)<input type="number" name="cooldown_minutes" min="1" max="1440" value="30"></label><label>Minimum confidence (%)<input type="number" name="minimum_confidence" min="0" max="100" value="0"></label></div><label class="check-row"><input type="checkbox" name="market_hours_only" value="1" checked> Market hours only</label><div class="notice info">A fresh prediction is always included when this alert triggers.</div><button class="button primary" type="submit">Create alert rule</button></form>
